export function assertEuPack() {
  for (const locale of EU_LOCALES) {
    if (!messagesEu[locale]?.tagline) throw new Error(`messagesEu ${locale}`);
    if (!extrasEu[locale]?.heroLead) throw new Error(`extrasEu ${locale}`);
    if (!uxEu[locale]?.homeTitle) throw new Error(`uxEu ${locale}`);
    if (!mailEu[locale]?.tools) throw new Error(`mailEu ${locale}`);
    if (!runnerEu[locale]?.chooseFile) throw new Error(`runnerEu ${locale}`);
  }
  for (const slug of LEGAL_SLUGS) {
    for (const locale of EU_LOCALES) {
      const body = legalEu(slug, locale);
      if (!body?.length || !body.join("\n").includes("tools@freela.store")) {
        throw new Error(`legalEu ${slug} ${locale}`);
      }
    }
  }
}
